import os
import unicodedata
import hashlib
import hmac
import re
from pathlib import PurePosixPath
from flask import Flask, request, jsonify, send_file
import secrets

app = Flask(__name__)
app.secret_key = secrets.token_hex(32)

BASE_DIR = '/srv/documents'
ALLOWED_EXTENSIONS = {'.pdf', '.txt', '.docx', '.xlsx', '.png', '.jpg'}
MAX_PATH_DEPTH = 4
SESSION_TOKENS = {}

def generate_token(user_id):
    token = secrets.token_urlsafe(32)
    SESSION_TOKENS[token] = {'user_id': user_id, 'role': 'viewer'}
    return token

def verify_token(token):
    return SESSION_TOKENS.get(token)

def sanitize_component(component):
    """Remove dangerous characters from a single path component."""
    # Strip null bytes and control characters
    cleaned = ''.join(c for c in component if ord(c) >= 0x20 and c != '\x7f')
    # Block obvious traversal
    if cleaned in ('.', '..', ''):
        return None
    # Block components starting with dot (hidden files)
    if cleaned.startswith('.'):
        return None
    return cleaned

def validate_path_security(filepath):
    """Multi-layer path validation to prevent directory traversal."""
    # Layer 1: Block URL-encoded sequences
    if '%' in filepath:
        return False, "URL encoding not allowed"

    # Layer 2: Block backslashes
    if '\\' in filepath:
        return False, "Backslashes not allowed"

    # Layer 3: Block null bytes
    if '\x00' in filepath:
        return False, "Null bytes not allowed"

    # Layer 4: Check for path traversal patterns
    if '..' in filepath:
        return False, "Path traversal detected"

    # Layer 5: Validate each component
    parts = filepath.split('/')
    if len(parts) > MAX_PATH_DEPTH:
        return False, "Path too deep"

    for part in parts:
        if part == '':
            continue
        result = sanitize_component(part)
        if result is None:
            return False, f"Invalid path component: {part}"

    # Layer 6: Check extension
    ext = os.path.splitext(filepath)[1].lower()
    if ext not in ALLOWED_EXTENSIONS:
        return False, f"Extension not allowed: {ext}"

    # Layer 7: Verify resolved path stays within BASE_DIR
    # Use PurePosixPath to check without filesystem access
    try:
        pure = PurePosixPath(filepath)
        if pure.is_absolute():
            return False, "Absolute paths not allowed"
    except (ValueError, TypeError):
        return False, "Invalid path format"

    return True, "OK"

def normalize_filename(filename):
    """Normalize Unicode characters in filename for consistent storage lookup.

    This handles cases where filenames were created with different Unicode
    normalization forms (NFC vs NFD). For example, 'u\u0308' (u + combining
    diaeresis) should match 'ü' (precomposed). We use NFKC for maximum
    compatibility with filesystem encodings.
    """
    return unicodedata.normalize('NFKC', filename)

@app.route('/api/auth', methods=['POST'])
def authenticate():
    data = request.get_json()
    if not data or 'username' not in data:
        return jsonify({'error': 'Missing credentials'}), 400
    # Simplified auth for demonstration
    token = generate_token(data['username'])
    return jsonify({'token': token})

@app.route('/api/documents/<path:filepath>', methods=['GET'])
def get_document(filepath):
    # Authentication check
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Authentication required'}), 401

    token = auth_header[7:]
    session = verify_token(token)
    if not session:
        return jsonify({'error': 'Invalid token'}), 401

    # Validate the path BEFORE normalization
    is_valid, reason = validate_path_security(filepath)
    if not is_valid:
        return jsonify({'error': reason}), 403

    # Normalize for consistent filesystem lookup
    # This ensures files created with different Unicode forms are accessible
    normalized = normalize_filename(filepath)

    # Construct the full path using the normalized version
    full_path = os.path.join(BASE_DIR, normalized)

    # Final safety check: resolve and verify containment
    try:
        resolved = os.path.realpath(full_path)
    except (OSError, ValueError):
        return jsonify({'error': 'Path resolution failed'}), 400

    if not resolved.startswith(os.path.realpath(BASE_DIR) + os.sep):
        return jsonify({'error': 'Access denied'}), 403

    if not os.path.isfile(resolved):
        return jsonify({'error': 'File not found'}), 404

    return send_file(resolved)

@app.route('/api/documents', methods=['POST'])
def upload_document():
    auth_header = request.headers.get('Authorization', '')
    if not auth_header.startswith('Bearer '):
        return jsonify({'error': 'Authentication required'}), 401

    token = auth_header[7:]
    session = verify_token(token)
    if not session:
        return jsonify({'error': 'Invalid token'}), 401

    if 'file' not in request.files or 'path' not in request.form:
        return jsonify({'error': 'Missing file or path'}), 400

    filepath = request.form['path']
    is_valid, reason = validate_path_security(filepath)
    if not is_valid:
        return jsonify({'error': reason}), 403

    normalized = normalize_filename(filepath)
    full_path = os.path.join(BASE_DIR, normalized)

    resolved_dir = os.path.realpath(os.path.dirname(full_path))
    if not resolved_dir.startswith(os.path.realpath(BASE_DIR)):
        return jsonify({'error': 'Access denied'}), 403

    os.makedirs(os.path.dirname(full_path), exist_ok=True)
    request.files['file'].save(full_path)

    return jsonify({'status': 'uploaded', 'path': normalized})

if __name__ == '__main__':
    os.makedirs(BASE_DIR, exist_ok=True)
    app.run(host='127.0.0.1', port=8080)
